package main

import (
	"fmt"
	"os"
	"strings"
)

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId string // PIC X(4) @0 len=4
	DtYyyy int64 // PIC 9(4) @4 len=4
	DtMm int64 // PIC 9(2) @8 len=2
	DtDd int64 // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsLeapFlag string = "N" // PIC X len=1 = "N"
var WsQ int64 // PIC 9(4) len=4 = 0
var WsR4 int64 // PIC 9(3) len=3 = 0
var WsR100 int64 // PIC 9(3) len=3 = 0
var WsR400 int64 // PIC 9(3) len=3 = 0
var WsMaxDay int64 // PIC 99 len=2 = 0
var WsValid int64 // PIC 99 len=2 = 0
var WsBadMonth int64 // PIC 99 len=2 = 0
var WsBadDay int64 // PIC 99 len=2 = 0

var dateRec DateRec
var inputLines []string
var inputIdx int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func isLeap() bool {
	return WsLeapFlag == "Y"
}

func truncPic(v int64, digits int) int64 {
	var mod int64 = 1
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	return v % mod
}

func parsePic9(s string) int64 {
	var v int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		} else if c == ' ' {
			v = v * 10
		} else {
			v = v * 10
		}
	}
	return v
}

func fmt2(v int64) string {
	v = ((v%100)+100)%100
	return fmt.Sprintf("%02d", v)
}

func fmt4(v int64) string {
	v = ((v%10000)+10000)%10000
	return fmt.Sprintf("%04d", v)
}

func MainPara() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	var lines []string
	if len(data) > 0 {
		start := 0
		for i := 0; i < len(data); i++ {
			if data[i] == '\n' {
				line := string(data[start:i])
				if len(line) > 0 && line[len(line)-1] == '\r' {
					line = line[:len(line)-1]
				}
				lines = append(lines, line)
				start = i + 1
			}
		}
		if start < len(data) {
			line := string(data[start:])
			if len(line) > 0 && line[len(line)-1] == '\r' {
				line = line[:len(line)-1]
			}
			lines = append(lines, line)
		}
	} else {
		lines = []string{}
	}
	_ = strings.Repeat
	inputLines = lines
	inputIdx = 0
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	out := "VALID: " + fmt2(WsValid) + " BAD MONTH: " + fmt2(WsBadMonth) + " BAD DAY: " + fmt2(WsBadDay) + "\n"
	os.Stdout.WriteString(out)
}

func ReadPara() {
	if inputIdx < len(inputLines) {
		line := inputLines[inputIdx]
		inputIdx++
		if len(line) < 12 {
			line = line + strings.Repeat(" ", 12-len(line))
		} else if len(line) > 12 {
			line = line[:12]
		}
		dateRec.DtId = line[0:4]
		dateRec.DtYyyy = parsePic9(line[4:8])
		dateRec.DtMm = parsePic9(line[8:10])
		dateRec.DtDd = parsePic9(line[10:12])
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	LeapPara()
	if dateRec.DtMm < 1 || dateRec.DtMm > 12 {
		WsBadMonth = truncPic(WsBadMonth+1, 2)
		if WsBadMonth < 0 {
			WsBadMonth = ((WsBadMonth%100)+100)%100
		}
		out := dateRec.DtId + " BAD MONTH " + fmt2(dateRec.DtMm) + "\n"
		os.Stdout.WriteString(out)
	} else {
		DaysPara()
		if dateRec.DtDd < 1 || dateRec.DtDd > WsMaxDay {
			WsBadDay = truncPic(WsBadDay+1, 2)
			if WsBadDay < 0 {
				WsBadDay = ((WsBadDay%100)+100)%100
			}
			out := dateRec.DtId + " BAD DAY " + fmt2(dateRec.DtDd) + " MAX " + fmt2(WsMaxDay) + "\n"
			os.Stdout.WriteString(out)
		} else {
			WsValid = truncPic(WsValid+1, 2)
			if WsValid < 0 {
				WsValid = ((WsValid%100)+100)%100
			}
			out := dateRec.DtId + " VALID " + fmt4(dateRec.DtYyyy) + "-" + fmt2(dateRec.DtMm) + "-" + fmt2(dateRec.DtDd) + "\n"
			os.Stdout.WriteString(out)
		}
	}
	ReadPara()
}

func LeapPara() {
	q := dateRec.DtYyyy / 4
	r := dateRec.DtYyyy % 4
	WsQ = truncPic(q, 4)
	WsR4 = truncPic(r, 3)
	q = dateRec.DtYyyy / 100
	r = dateRec.DtYyyy % 100
	WsQ = truncPic(q, 4)
	WsR100 = truncPic(r, 3)
	q = dateRec.DtYyyy / 400
	r = dateRec.DtYyyy % 400
	WsQ = truncPic(q, 4)
	WsR400 = truncPic(r, 3)
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DaysPara() {
	switch dateRec.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
}

func main() {
	MainPara()
}
